mapper.select:
SELECT
	mr.*
FROM
	smt_msg_record mr INNER JOIN smt_msg_template mt ON mr.temp_id=mt.id
WHERE
	mr.delete_state = 0
	AND mr.msg_object = #{msgObject}

	AND mt.msg_type=#{msgType}


	AND mr.read_state=#{readState}


	AND mr.create_time >= #{startTime}


	AND mr.create_time <= #{endTime}

ORDER BY mr.read_state,mr.create_time DESC

SELECT
		mr.*
	FROM
		smt_msg_record mr INNER JOIN smt_msg_template mt ON mr.temp_id=mt.id
	WHERE
		mr.delete_state = 0
		AND mr.msg_object = #{msgObject}

		AND mt.msg_type=#{msgType}


		AND mr.read_state=#{readState}

SELECT
	count(1)
FROM
	smt_msg_record mr INNER JOIN smt_msg_template mt ON mr.temp_id=mt.id
WHERE 1=1

	AND mt.temp_code=#{tempCode}


	AND mt.msg_type=#{msgType}


	AND mr.temp_id=#{condition.tempId}


	AND mr.msg_object=#{condition.msgObject}


	AND mr.read_state=#{condition.readState}


	AND mr.msg_state=#{condition.msgState}


	AND mr.delete_state=#{condition.deleteState}


	AND mr.create_time >= #{startTime}


	AND mr.create_time <= #{endTime}

SELECT
mr.*
FROM
smt_msg_record mr INNER JOIN smt_msg_template mt ON mr.temp_id=mt.id
WHERE mt.msg_type = 1
AND mr.delete_state = 0


		AND mr.msg_object = #{query.phoneNo}


		AND mr.msg_state=#{query.msgState}


		AND mr.temp_id=#{query.tempId}


		AND mr.create_time >= #{query.startTime}


		AND mr.create_time <= #{query.endTime}


ORDER BY mr.create_time DESC
